/**
 * Jharkhand Tourism - Interactive Map Controller
 * Leaflet.js integration with custom markers, smooth flyTo camera, and filtering.
 */

let jharkhandMap = null;
let mapMarkers = [];
let markerLayerGroup = null;

// Default Geographic Center of Jharkhand
const JHARKHAND_CENTER = {
  lat: 23.6102,
  lng: 85.2799,
  defaultZoom: 8,
  focusZoom: 12
};

/**
 * Initialize the Leaflet Map with CartoDB Dark Matter / Voyager tiles
 */
function initJharkhandMap() {
  const mapElement = document.getElementById("jharkhand-map");
  if (!mapElement) return;

  // Initialize Map
  jharkhandMap = L.map("jharkhand-map", {
    center: [JHARKHAND_CENTER.lat, JHARKHAND_CENTER.lng],
    zoom: JHARKHAND_CENTER.defaultZoom,
    minZoom: 6,
    maxZoom: 17,
    zoomControl: true,
    scrollWheelZoom: false // Prevent accidental scrolling while browsing page
  });

  // Enable scroll zoom only after user clicks/focuses on map
  jharkhandMap.on("focus", () => jharkhandMap.scrollWheelZoom.enable());
  jharkhandMap.on("blur", () => jharkhandMap.scrollWheelZoom.disable());

  // Base Map Layer (CartoDB Dark Matter for luxury night aesthetic)
  L.tileLayer("https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png", {
    attribution: '&copy; <a href="https://carto.com/">CARTO</a> | &copy; Jharkhand Tourism',
    subdomains: "abcd",
    maxZoom: 19
  }).addTo(jharkhandMap);

  markerLayerGroup = L.layerGroup().addTo(jharkhandMap);

  // Render Markers
  renderMapMarkers(JHARKHAND_DESTINATIONS);

  // Map Filter Buttons Event Listener
  setupMapFilterEvents();
}

/**
 * Render custom SVG markers onto the map
 * @param {Array} destinations
 */
function renderMapMarkers(destinations) {
  if (!markerLayerGroup) return;
  markerLayerGroup.clearLayers();
  mapMarkers = [];

  destinations.forEach((dest) => {
    const isFamous = dest.type === "famous";
    const markerClass = isFamous ? "marker-famous" : "marker-underrated";
    const typeLabel = isFamous ? "Famous" : "Underrated";
    const badgeClass = isFamous ? "famous" : "underrated";

    // Custom Icon SVG markup
    const customIconHtml = `
      <div class="custom-map-marker ${markerClass}">
        <div class="marker-pin">
          <div class="marker-icon-inner">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
              <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path>
              <circle cx="12" cy="10" r="3"></circle>
            </svg>
          </div>
        </div>
      </div>
    `;

    const customIcon = L.divIcon({
      html: customIconHtml,
      className: "custom-leaflet-div-icon",
      iconSize: [40, 40],
      iconAnchor: [20, 38],
      popupAnchor: [0, -40]
    });

    // Marker Popup HTML
    const popupContent = `
      <div class="map-popup-card">
        <div class="map-popup-thumb-wrap">
          <img src="${dest.thumbnail}" alt="${dest.name}" class="map-popup-img" loading="lazy" />
          <div class="map-popup-overlay"></div>
          <span class="map-popup-type-badge ${badgeClass}">${typeLabel}</span>
        </div>
        <div class="map-popup-info">
          <h4 class="map-popup-title">${dest.name}</h4>
          <div class="map-popup-meta">
            <span>${dest.category}</span> • <span>${dest.district}</span>
          </div>
          <div class="map-popup-cta" onclick="openDestinationModal('${dest.id}')">
            <span>Explore Details</span>
            <span>→</span>
          </div>
        </div>
      </div>
    `;

    const marker = L.marker([dest.coordinates.lat, dest.coordinates.lng], {
      icon: customIcon,
      title: dest.name
    }).bindPopup(popupContent);

    marker.destinationId = dest.id;
    marker.destinationData = dest;

    markerLayerGroup.addLayer(marker);
    mapMarkers.push(marker);
  });
}

/**
 * Focus and smooth fly-to on a specific destination
 * @param {string} destinationId
 */
function focusDestinationOnMap(destinationId) {
  const destination = JHARKHAND_DESTINATIONS.find((d) => d.id === destinationId);
  if (!destination || !jharkhandMap) return;

  // Scroll to Map Section smoothly
  const mapSection = document.getElementById("map-section");
  if (mapSection) {
    mapSection.scrollIntoView({ behavior: "smooth", block: "center" });
  }

  // Smooth camera flyTo
  setTimeout(() => {
    jharkhandMap.flyTo(
      [destination.coordinates.lat, destination.coordinates.lng],
      JHARKHAND_CENTER.focusZoom,
      {
        duration: 1.4,
        easeLinearity: 0.25
      }
    );

    // Open matching marker popup
    const targetMarker = mapMarkers.find((m) => m.destinationId === destinationId);
    if (targetMarker) {
      setTimeout(() => targetMarker.openPopup(), 1200);
    }
  }, 350);
}

/**
 * Reset map view back to entire Jharkhand overview
 */
function resetJharkhandMapView() {
  if (!jharkhandMap) return;
  jharkhandMap.closePopup();
  jharkhandMap.flyTo(
    [JHARKHAND_CENTER.lat, JHARKHAND_CENTER.lng],
    JHARKHAND_CENTER.defaultZoom,
    {
      duration: 1.2
    }
  );
}

/**
 * Setup filter chip event listeners on the map
 */
function setupMapFilterEvents() {
  const filterButtons = document.querySelectorAll(".map-filter-btn");
  filterButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      filterButtons.forEach((b) => b.classList.remove("active"));
      btn.classList.add("active");

      const filterType = btn.dataset.filter;
      if (filterType === "all") {
        renderMapMarkers(JHARKHAND_DESTINATIONS);
      } else if (filterType === "famous" || filterType === "underrated") {
        const filtered = JHARKHAND_DESTINATIONS.filter((d) => d.type === filterType);
        renderMapMarkers(filtered);
      } else if (filterType === "waterfalls") {
        const filtered = JHARKHAND_DESTINATIONS.filter((d) =>
          d.category.toLowerCase().includes("waterfall")
        );
        renderMapMarkers(filtered);
      } else if (filterType === "wildlife") {
        const filtered = JHARKHAND_DESTINATIONS.filter((d) =>
          d.category.toLowerCase().includes("wildlife") || d.category.toLowerCase().includes("forest")
        );
        renderMapMarkers(filtered);
      }
    });
  });

  const resetBtn = document.querySelector(".map-reset-btn");
  if (resetBtn) {
    resetBtn.addEventListener("click", () => {
      filterButtons.forEach((b) => b.classList.remove("active"));
      document.querySelector('.map-filter-btn[data-filter="all"]')?.classList.add("active");
      renderMapMarkers(JHARKHAND_DESTINATIONS);
      resetJharkhandMapView();
    });
  }
}

// Export functions to global scope
window.initJharkhandMap = initJharkhandMap;
window.focusDestinationOnMap = focusDestinationOnMap;
window.resetJharkhandMapView = resetJharkhandMapView;

/**
 * Jharkhand Tourism - Main Application Logic
 * Elevated UI/UX Controller, Modal Manager, Custom Cursor, Audio Generator, and Animations
 */

document.addEventListener("DOMContentLoaded", () => {
  // 1. Initialize Loading Screen
  initPreloader();

  // 2. Initialize Navigation & Scroll Listeners
