function initCategoryFilters() {
  const filterChips = document.querySelectorAll(".filter-chip");
  const destinationCards = document.querySelectorAll(".destination-card, .underrated-card");

  filterChips.forEach((chip) => {
    chip.addEventListener("click", () => {
      filterChips.forEach((c) => c.classList.remove("active"));
      chip.classList.add("active");

      const selectedCategory = chip.dataset.category.toLowerCase();

      document.querySelectorAll(".destination-card, .underrated-card").forEach((card) => {
        const cardCat = card.dataset.category || "";
        if (selectedCategory === "all" || cardCat.includes(selectedCategory)) {
          card.style.display = "flex";
