/* ==========================================================================
   5. DESKTOP CUSTOM CURSOR FOLLOWER FOR CARDS
   ========================================================================== */
function initCardCursorFollower() {
  const follower = document.getElementById("card-cursor-follower");
  if (!follower) return;

  // Check if pointer is fine and hover is supported (Desktop only)
  const isFinePointer = window.matchMedia("(hover: hover) and (pointer: fine)").matches;
  if (!isFinePointer) return;

  let mouseX = 0, mouseY = 0;
  let followerX = 0, followerY = 0;
  let isHoveringCard = false;

  document.addEventListener("mousemove", (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;

    const targetCard = e.target.closest(".destination-card, .underrated-card, .theme-card");
    if (targetCard) {
      if (!isHoveringCard) {
        follower.classList.add("active");
        follower.textContent = targetCard.classList.contains("underrated-card") ? "DISCOVER" : "EXPLORE";
        isHoveringCard = true;
      }
    } else {
      if (isHoveringCard) {
        follower.classList.remove("active");
        isHoveringCard = false;
      }
    }
  });

  // Smooth fluid trailing animation using requestAnimationFrame
  function animateFollower() {
    followerX += (mouseX - followerX) * 0.18;
    followerY += (mouseY - followerY) * 0.18;

    follower.style.transform = `translate3d(${followerX}px, ${followerY}px, 0) ${isHoveringCard ? 'scale(1)' : 'scale(0.5)'}`;
    requestAnimationFrame(animateFollower);
  }

  animateFollower();
}

