  letter-spacing: 0.12em;
  color: var(--text-pure);
  text-transform: uppercase;
}

.brand-text span {
  color: var(--gold-prime);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2.25rem;
  list-style: none;
}

.nav-link {
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  color: var(--text-main);
  position: relative;
  padding: 0.4rem 0;
  transition: color var(--transition-fast);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1.5px;
  background: var(--gold-prime);
  transition: width var(--transition-normal);
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-pure);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1.25rem;
}

/* ==========================================================================
   MAD FEATURE: EXPLORER PASSPORT BADGE (NAVBAR & FLOATING)
   ========================================================================== */
.passport-nav-btn {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.55rem 1.1rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--gold-prime);
  background: linear-gradient(135deg, rgba(197, 160, 89, 0.15), rgba(16, 185, 129, 0.1));
  color: var(--gold-light);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: all var(--transition-fast);
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(197, 160, 89, 0.2);
}

.passport-nav-btn:hover {
  background: var(--gold-prime);
  color: #061A13;
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(197, 160, 89, 0.45);
}

.passport-badge-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--gold-prime);
  color: #061A13;
  font-weight: 700;
  font-size: 0.72rem;
}

.passport-nav-btn:hover .passport-badge-count {
  background: #061A13;
  color: var(--gold-prime);
}

/* Floating Unlock Notification Toast */
.unlock-toast {
  position: fixed;
  top: 100px;
  right: 2rem;
  z-index: 100000;
  background: rgba(7, 31, 23, 0.95);
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
  border: 1.5px solid var(--gold-prime);
  border-radius: var(--radius-md);
  padding: 1.25rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 1.25rem;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8), 0 0 25px rgba(197, 160, 89, 0.4);
  transform: translateX(120%);
  transition: transform 0.6s var(--ease-spring), opacity 0.6s;
  pointer-events: auto;
  max-width: 420px;
}

.unlock-toast.show {
  transform: translateX(0);
}

.unlock-toast-icon {
  font-size: 2.25rem;
  animation: stamp-drop 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes stamp-drop {
  0% { transform: scale(3) rotate(-25deg); opacity: 0; }
  100% { transform: scale(1) rotate(0deg); opacity: 1; }
}

.unlock-toast-title {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gold-prime);
}

.unlock-toast-place {
  font-family: var(--font-serif);
  font-size: 1.2rem;
  color: var(--text-pure);
  margin-bottom: 2px;
}

.unlock-toast-xp {
  font-size: 0.8rem;
  color: #34D399;
  font-weight: 600;
}

/* Primary CTA Button */
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--gold-prime);
  color: #061A13;
  font-weight: 600;
  font-size: 0.82rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.85rem 1.6rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--gold-prime);
  transition: all var(--transition-normal);
  position: relative;
  overflow: hidden;
  box-shadow: 0 8px 20px -5px rgba(197, 160, 89, 0.35);
}

.btn-primary::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);
  transition: left 0.6s ease;
}

.btn-primary:hover {
  background: var(--gold-light);
  border-color: var(--gold-light);
  transform: translateY(-2px);
  box-shadow: 0 12px 30px -5px rgba(197, 160, 89, 0.5);
}

.btn-primary:hover::before {
  left: 100%;
}

.btn-primary .btn-arrow {
  transition: transform var(--transition-fast);
}

.btn-primary:hover .btn-arrow {
  transform: translateX(5px);
}

/* Secondary Button / Outline */
.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  background: transparent;
  color: var(--text-pure);
  font-weight: 500;
  font-size: 0.82rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0.85rem 1.6rem;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.2);
  transition: all var(--transition-normal);
  backdrop-filter: blur(8px);
}

.btn-secondary:hover {
  border-color: var(--gold-prime);
  color: var(--gold-prime);
  background: rgba(197, 160, 89, 0.08);
  transform: translateY(-2px);
  box-shadow: 0 8px 20px -5px rgba(0, 0, 0, 0.5);
}

/* Mobile Hamburger Toggle */
.mobile-nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 6px;
  width: 44px;
  height: 44px;
  padding: 8px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--glass-border);
  background: rgba(255, 255, 255, 0.03);
  z-index: 1001;
}

.mobile-nav-toggle span {
  display: block;
  height: 2px;
  width: 100%;
  background: var(--text-pure);
  border-radius: 1px;
  transition: all var(--transition-normal);
}

.mobile-nav-toggle.open span:nth-child(1) {
  transform: translateY(8px) rotate(45deg);
}
.mobile-nav-toggle.open span:nth-child(2) {
  opacity: 0;
}
.mobile-nav-toggle.open span:nth-child(3) {
  transform: translateY(-8px) rotate(-45deg);
}

/* Mobile Navigation Drawer */
.mobile-drawer {
  position: fixed;
  inset: 0;
  background: rgba(4, 15, 11, 0.98);
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
  z-index: 999;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 3rem 2rem;
  transform: translateX(100%);
  transition: transform 0.6s var(--ease-luxury);
  pointer-events: none;
}

.mobile-drawer.open {
  transform: translateX(0);
  pointer-events: auto;
}

.mobile-drawer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
  margin-bottom: 2.5rem;
}

.mobile-drawer-link {
  font-family: var(--font-serif);
  font-size: 2rem;
  color: var(--text-main);
  text-decoration: none;
  transition: color var(--transition-fast);
}

.mobile-drawer-link:hover,
.mobile-drawer-link.active {
  color: var(--gold-prime);
}

/* --------------------------------------------------------------------------
   HERO SECTION (CINEMATIC FULLSCREEN)
   -------------------------------------------------------------------------- */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  padding: 8rem 1.5rem 5rem;
}

.hero-bg-container {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.hero-bg-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  animation: var(--transition-kenburns);
  transform-origin: center center;
  filter: brightness(0.85);
  will-change: transform;
}

/* Glowing Ambient Floating Orbs in Hero */
.hero-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.35;
  pointer-events: none;
  z-index: 1;
}

.hero-orb-1 {
  top: 15%;
  left: 20%;
  width: 320px;
  height: 320px;
  background: radial-gradient(circle, #C5A059, transparent 70%);
  animation: float-orb 12s ease-in-out infinite alternate;
}

.hero-orb-2 {
  bottom: 20%;
  right: 15%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, #10B981, transparent 70%);
  animation: float-orb 16s ease-in-out infinite 2s alternate-reverse;
}

@keyframes float-orb {
  0% { transform: translate(0, 0) scale(1); }
  100% { transform: translate(40px, -30px) scale(1.15); }
}

/* Dark Editorial Gradient Vignette */
.hero-overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(6, 26, 19, 0.45) 0%, rgba(4, 15, 11, 0.85) 85%),
              linear-gradient(to bottom, rgba(6, 26, 19, 0.5) 0%, transparent 40%, rgba(6, 26, 19, 0.95) 100%);
  z-index: 1;
}

@keyframes kenburns {
  0% {
    transform: scale(1) translate(0, 0);
  }
  50% {
    transform: scale(1.08) translate(-1%, -1%);
  }
  100% {
    transform: scale(1.14) translate(1%, 0.5%);
  }
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 920px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  margin-top: 1rem;
}

.hero-tag {
  font-family: var(--font-sans);
  font-size: clamp(0.8rem, 1.2vw, 0.95rem);
  font-weight: 600;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: var(--gold-prime);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.hero-tag::before,
.hero-tag::after {
  content: '';
  width: 30px;
  height: 1px;
  background: var(--gold-prime);
}

.hero-title {
  font-size: clamp(2.75rem, 6.5vw, 5.5rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  color: #FFFFFF;
  line-height: 1.05;
  text-shadow: 0 10px 40px rgba(0, 0, 0, 0.6);
}

.hero-title span {
  font-style: italic;
  font-weight: 300;
  color: #F8F5EE;
}

.hero-subtitle {
  font-size: clamp(1.1rem, 2vw, 1.45rem);
  font-weight: 300;
  color: var(--gold-light);
  font-family: var(--font-serif);
  font-style: italic;
  letter-spacing: 0.02em;
}

.hero-description {
  font-size: clamp(0.95rem, 1.2vw, 1.125rem);
  color: var(--text-main);
  max-width: 640px;
  font-weight: 300;
  opacity: 0.9;
  line-height: 1.6;
}

.hero-buttons {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  margin-top: 1.25rem;
  flex-wrap: wrap;
}

/* Scroll Indicator */
.hero-scroll-indicator {
  position: absolute;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  color: var(--text-muted);
  font-size: 0.72rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  transition: color var(--transition-fast), transform var(--transition-fast);
}

.hero-scroll-indicator:hover {
  color: var(--gold-prime);
  transform: translateX(-50%) translateY(3px);
}

.scroll-mouse {
  width: 20px;
  height: 32px;
  border: 1.5px solid rgba(255, 255, 255, 0.35);
  border-radius: 10px;
  display: flex;
  justify-content: center;
  padding-top: 6px;
}

.scroll-wheel {
  width: 3px;
  height: 6px;
  background: var(--gold-prime);
  border-radius: 2px;
  animation: scroll-bob 2s ease-in-out infinite;
}

@keyframes scroll-bob {
  0% { transform: translateY(0); opacity: 1; }
  60% { transform: translateY(8px); opacity: 0; }
  61% { transform: translateY(0); opacity: 0; }
  100% { transform: translateY(0); opacity: 1; }
}

/* --------------------------------------------------------------------------
   EDITORIAL STATS STRIP / ANIMATED STATS COUNTER
   -------------------------------------------------------------------------- */
.stats-strip {
  border-top: 1px solid var(--glass-border);
  border-bottom: 1px solid var(--glass-border);
  background: rgba(11, 36, 27, 0.4);
  backdrop-filter: blur(10px);
  padding: 2.5rem 0;
  position: relative;
  z-index: 2;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.stat-item {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  border-left: 1px solid rgba(197, 160, 89, 0.25);
  padding-left: 1.5rem;
  transition: transform var(--transition-normal);
}

.stat-item:hover {
  transform: translateX(4px);
}

.stat-number {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 3.5vw, 2.75rem);
  font-weight: 500;
  color: var(--gold-light);
  line-height: 1;
}

.stat-label {
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-pure);
}

.stat-desc {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.4;
}

/* --------------------------------------------------------------------------
   DESTINATIONS GRID & EDITORIAL CARDS
   -------------------------------------------------------------------------- */
.destinations-section {
  position: relative;
  background-color: var(--bg-prime);
}

.filter-bar {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 3rem;
  padding-bottom: 1rem;
}

.filter-chip {
  padding: 0.65rem 1.35rem;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.02);
  color: var(--text-muted);
  font-size: 0.82rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  transition: all 0.35s var(--ease-luxury);
  position: relative;
  overflow: hidden;
}

.filter-chip:hover {
  border-color: var(--gold-prime);
  color: var(--text-pure);
  background: rgba(197, 160, 89, 0.08);
  transform: translateY(-2px);
}

.filter-chip.active {
  border-color: var(--gold-prime);
  background: var(--gold-prime);
  color: #061A13;
  font-weight: 600;
  box-shadow: 0 4px 15px rgba(197, 160, 89, 0.4);
}

/* Cards Grid */
.destinations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
  gap: clamp(1.75rem, 2.5vw, 2.5rem);
}

/* ==========================================================================
   DESTINATION CARD (CINEMATIC 3D TILT HOVER & HOVER MECHANICS)
   ========================================================================== */
.destination-card {
  position: relative;
  height: 500px;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-card);
  cursor: pointer;
  box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.06);
  transition: border-color 0.6s var(--ease-luxury), box-shadow 0.6s var(--ease-luxury), transform 0.6s var(--ease-luxury);
  will-change: transform, box-shadow;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  transform-style: preserve-3d;
}

/* Dynamic Specular Sheen Beam sweeping across on hover */
.destination-card::after {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(
    45deg,
    transparent 40%,
    rgba(255, 255, 255, 0.12) 50%,
    transparent 60%
  );
  transform: rotate(-45deg) translateY(-100%);
  transition: transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
  z-index: 4;
}

.destination-card:hover::after {
  transform: rotate(-45deg) translateY(100%);
}

.destination-card:hover {
  border-color: rgba(197, 160, 89, 0.5);
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.75), 0 0 25px -5px rgba(197, 160, 89, 0.3);
  transform: translateY(-6px);
}

/* Image Container */
.card-media {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transform: scale(1);
  transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1), filter 0.8s ease;
  will-change: transform;
}

/* Hover: Zoom scale(1.08) + subtle shift */
.destination-card:hover .card-img {
  transform: scale(1.08) translate3d(-1%, -1%, 0);
  filter: contrast(1.05);
}

/* Hover: Dark gradient overlay intensifies */
.card-gradient {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(
    to bottom,
    rgba(6, 26, 19, 0.15) 0%,
    rgba(6, 26, 19, 0.4) 40%,
    rgba(4, 15, 11, 0.85) 75%,
    rgba(4, 15, 11, 0.98) 100%
  );
  transition: background 0.6s var(--ease-luxury);
}

.destination-card:hover .card-gradient {
  background: linear-gradient(
    to bottom,
    rgba(6, 26, 19, 0.25) 0%,
    rgba(6, 26, 19, 0.55) 35%,
    rgba(4, 15, 11, 0.92) 70%,
    rgba(4, 15, 11, 1) 100%
  );
}

/* Floating Top Badges & Passport Stamp Status */
.card-top-meta {
  position: absolute;
  top: 1.5rem;
  left: 1.5rem;
  right: 1.5rem;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  pointer-events: none;
}

.badge-famous {
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-full);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  background: rgba(197, 160, 89, 0.2);
  border: 1px solid rgba(197, 160, 89, 0.4);
  color: var(--gold-light);
}

.badge-unlocked {
  background: rgba(16, 185, 129, 0.25) !important;
  border-color: rgba(16, 185, 129, 0.6) !important;
  color: #34D399 !important;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.card-district {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  color: var(--text-main);
  background: rgba(0, 0, 0, 0.5);
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius-full);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

/* Card Body Content */
.card-body {
  position: relative;
  z-index: 2;
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  transform: translateY(0);
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Hover: Title moves upward smoothly */
.destination-card:hover .card-body {
  transform: translateY(-6px);
}

.card-category {
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-prime);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  opacity: 0.85;
  transition: opacity 0.4s var(--ease-luxury), transform 0.4s var(--ease-luxury);
}

.destination-card:hover .card-category {
  opacity: 1;
}

.card-title {
  font-family: var(--font-serif);
  font-size: 1.65rem;
  font-weight: 500;
  color: var(--text-pure);
  line-height: 1.2;
}

.card-tagline {
  font-size: 0.88rem;
  color: var(--text-muted);
  line-height: 1.45;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Hover: Explore -> slides in smoothly + arrow movement */
.card-cta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.75rem;
  padding-top: 0.85rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.card-explore-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gold-light);
  transition: color var(--transition-fast);
}

.card-explore-btn svg {
  width: 16px;
  height: 16px;
  transition: transform 0.4s var(--ease-luxury);
}

.destination-card:hover .card-explore-btn svg {
  transform: translateX(5px);
}

.card-map-action {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: var(--text-muted);
  transition: all var(--transition-fast);
}

.card-map-action:hover {
  background: var(--gold-prime);
  border-color: var(--gold-prime);
  color: #061A13;
  transform: scale(1.15) rotate(12deg);
}

/* ==========================================================================
   DESKTOP CUSTOM CURSOR FOLLOWER
   Active strictly within destination cards
   ========================================================================== */
.card-cursor-follower {
  position: fixed;
  top: 0;
  left: 0;
  width: 72px;
  height: 72px;
  margin-left: -36px;
  margin-top: -36px;
  border-radius: 50%;
  background: rgba(197, 160, 89, 0.9);
  color: #061A13;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  z-index: 10000;
  opacity: 0;
  transform: scale(0.5);
  transition: opacity 0.3s var(--ease-luxury), transform 0.3s var(--ease-luxury);
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(4px);
}

.card-cursor-follower.active {
  opacity: 1;
  transform: scale(1);
}

/* --------------------------------------------------------------------------
   "DID YOU KNOW?" EDITORIAL MOMENTS & MYSTERY RELIC REVEAL
   -------------------------------------------------------------------------- */
.editorial-break {
  position: relative;
  background: #04120D;
  border-top: 1px solid var(--glass-border);
  border-bottom: 1px solid var(--glass-border);
  overflow: hidden;
  padding: 5rem 0;
}

.editorial-break::before {
  content: '';
  position: absolute;
  top: -50%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 300px;
  background: radial-gradient(ellipse at center, rgba(197, 160, 89, 0.08) 0%, transparent 70%);
  pointer-events: none;
}

.fact-carousel-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.fact-card {
  background: rgba(11, 36, 27, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  padding: 2.25rem;
  position: relative;
  transition: all var(--transition-normal);
}

.fact-card:hover {
  border-color: rgba(197, 160, 89, 0.35);
  background: rgba(11, 36, 27, 0.7);
  transform: translateY(-4px);
}

.fact-num {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 400;
  color: var(--gold-prime);
  opacity: 0.4;
  line-height: 1;
  margin-bottom: 0.5rem;
}

.fact-tag {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold-prime);
  margin-bottom: 0.75rem;
}

.fact-headline {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  color: var(--text-pure);
  margin-bottom: 0.75rem;
  line-height: 1.35;
}

.fact-body {
  font-size: 0.88rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* --------------------------------------------------------------------------
   INTERACTIVE MAP SECTION
   -------------------------------------------------------------------------- */
.map-section {
  position: relative;
  background: #051610;
  border-top: 1px solid var(--glass-border);
}

.map-wrapper {
  position: relative;
  width: 100%;
  height: 640px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-shadow);
}

#jharkhand-map {
  width: 100%;
  height: 100%;
  background: #081D15;
  z-index: 1;
}

.map-controls-bar {
  position: absolute;
  top: 1.25rem;
  left: 1.25rem;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.map-filter-btn {
  padding: 0.5rem 1rem;
  border-radius: var(--radius-full);
  background: rgba(6, 26, 19, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--text-main);
  font-size: 0.78rem;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  transition: all var(--transition-fast);
}

.map-filter-btn:hover,
.map-filter-btn.active {
  background: var(--gold-prime);
  border-color: var(--gold-prime);
  color: #061A13;
  font-weight: 600;
  transform: translateY(-1px);
}

.map-reset-btn {
  padding: 0.5rem 1rem;
  border-radius: var(--radius-full);
  background: rgba(6, 26, 19, 0.85);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--text-muted);
  font-size: 0.78rem;
  transition: all var(--transition-fast);
}

.map-reset-btn:hover {
  color: var(--text-pure);
  border-color: var(--text-pure);
  transform: translateY(-1px);
}

.map-legend {
  position: absolute;
  bottom: 1.25rem;
  right: 1.25rem;
  z-index: 10;
  background: rgba(6, 26, 19, 0.9);
  backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  padding: 0.85rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.75rem;
  color: var(--text-main);
}

.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gold-prime);
  box-shadow: 0 0 10px var(--gold-prime);
}

/* --------------------------------------------------------------------------
   TRAVEL EXPERIENCES & CURATED THEMES
   -------------------------------------------------------------------------- */
.themes-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.75rem;
}

.theme-card {
  position: relative;
  height: 380px;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-shadow);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 2rem;
  transition: all var(--transition-normal);
}

.theme-card:hover {
  transform: translateY(-5px);
  border-color: var(--gold-prime);
  box-shadow: 0 25px 45px -10px rgba(0, 0, 0, 0.8), 0 0 20px -5px rgba(197, 160, 89, 0.25);
}

.theme-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.theme-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.8s var(--ease-luxury);
}

.theme-card:hover .theme-img {
  transform: scale(1.08);
}

.theme-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(4, 15, 11, 0.95) 0%, rgba(4, 15, 11, 0.4) 60%, transparent 100%);
  z-index: 1;
}

.theme-content {
  position: relative;
  z-index: 2;
}

.theme-count {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gold-prime);
  margin-bottom: 0.35rem;
}

.theme-title {
  font-family: var(--font-serif);
  font-size: 1.4rem;
  color: var(--text-pure);
  margin-bottom: 0.35rem;
}

.theme-sub {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.4;
}

/* ==========================================================================
   MAD FEATURE: EXPLORER PASSPORT MODAL (DIGITAL PASSPORT BOOK)
   ========================================================================== */
.passport-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100000;
  background: rgba(2, 8, 6, 0.92);
  backdrop-filter: blur(30px);
  -webkit-backdrop-filter: blur(30px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.5s var(--ease-luxury), visibility 0.5s;
  padding: 1.5rem;
}

.passport-modal-backdrop.open {
  opacity: 1;
  visibility: visible;
}

.passport-book {
  position: relative;
  width: 100%;
  max-width: 1020px;
  max-height: 88vh;
  background: linear-gradient(135deg, #092017 0%, #05140F 100%);
  border: 2px solid var(--gold-prime);
  border-radius: var(--radius-lg);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.9), 0 0 40px rgba(197, 160, 89, 0.25);
  overflow-y: auto;
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
  transform: scale(0.94);
  transition: transform 0.5s var(--ease-spring);
}

.passport-modal-backdrop.open .passport-book {
  transform: scale(1);
}

.passport-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(197, 160, 89, 0.3);
  padding-bottom: 1.5rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.passport-title-wrap {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.passport-emblem {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  border: 2px solid var(--gold-prime);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
  background: rgba(197, 160, 89, 0.15);
  box-shadow: 0 0 20px rgba(197, 160, 89, 0.3);
}

.passport-rank-badge {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gold-prime);
}

.passport-user-rank {
  font-family: var(--font-serif);
  font-size: 1.8rem;
  color: var(--text-pure);
}

.passport-progress-summary {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.passport-level-pill {
  background: rgba(197, 160, 89, 0.15);
  border: 1px solid var(--gold-prime);
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-full);
  color: var(--gold-light);
  font-size: 0.85rem;
  font-weight: 600;
}

/* Passport Stamps Grid */
.passport-stamps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.5rem;
}

.passport-stamp-slot {
  position: relative;
  height: 220px;
  border-radius: var(--radius-md);
  border: 1.5px dashed rgba(197, 160, 89, 0.35);
  background: rgba(4, 15, 11, 0.6);
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  transition: all 0.4s var(--ease-luxury);
  overflow: hidden;
}

.passport-stamp-slot.unlocked {
  border-style: solid;
  border-color: var(--gold-prime);
  background: rgba(11, 36, 27, 0.8);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), inset 0 0 20px rgba(197, 160, 89, 0.15);
}

.stamp-seal-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  background: rgba(16, 185, 129, 0.3);
  border: 1px solid #10B981;
  color: #34D399;
}

.stamp-thumbnail-mini {
  width: 70px;
  height: 70px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--gold-prime);
  margin-bottom: 0.75rem;
  box-shadow: 0 0 15px rgba(197, 160, 89, 0.3);
}

.stamp-locked-icon {
  font-size: 2.5rem;
  opacity: 0.35;
  margin-bottom: 0.5rem;
}

.stamp-place-name {
  font-family: var(--font-serif);
  font-size: 1.05rem;
  color: var(--text-pure);
  line-height: 1.2;
  margin-bottom: 4px;
}

.stamp-clue {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.35;
}

.passport-footer-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid rgba(197, 160, 89, 0.2);
  padding-top: 1.5rem;
  flex-wrap: wrap;
  gap: 1rem;
}

/* --------------------------------------------------------------------------
   FULL-SCREEN IMMERSIVE DESTINATION DETAILS MODAL
   -------------------------------------------------------------------------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(3, 12, 9, 0.88);
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.5s var(--ease-luxury), visibility 0.5s;
  padding: 1.5rem;
}

.modal-backdrop.open {
  opacity: 1;
  visibility: visible;
}

.destination-modal {
  position: relative;
  width: 100%;
  max-width: 1060px;
  max-height: 90vh;
  background: #071F17;
  border: 1px solid var(--glass-border-gold);
  border-radius: var(--radius-lg);
  overflow-y: auto;
  overflow-x: hidden;
  box-shadow: 0 30px 80px -15px rgba(0, 0, 0, 0.8);
  transform: translateY(30px) scale(0.96);
  transition: transform 0.5s var(--ease-luxury);
}

.modal-backdrop.open .destination-modal {
  transform: translateY(0) scale(1);
}

.modal-close-btn {
  position: absolute;
  top: 1.5rem;
  right: 1.5rem;
  z-index: 20;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--text-pure);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.modal-close-btn:hover {
  background: var(--gold-prime);
  border-color: var(--gold-prime);
  color: #061A13;
  transform: rotate(90deg);
}

/* Modal Hero Header */
.modal-hero {
  position: relative;
  height: 380px;
  width: 100%;
  overflow: hidden;
}

.modal-hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  animation: modal-img-reveal 0.8s var(--ease-luxury);
}

@keyframes modal-img-reveal {
  0% { transform: scale(1.1); filter: blur(8px); }
  100% { transform: scale(1); filter: blur(0); }
}

.modal-hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(7, 31, 23, 0.2) 0%,
    rgba(7, 31, 23, 0.6) 50%,
    rgba(7, 31, 23, 1) 100%
  );
}

.modal-hero-text {
  position: absolute;
  bottom: 2rem;
  left: 2.5rem;
  right: 2.5rem;
  z-index: 2;
}

.modal-badge-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.modal-title {
  font-size: clamp(2rem, 4vw, 3rem);
  color: var(--text-pure);
  margin-bottom: 0.35rem;
}

.modal-tagline {
  font-family: var(--font-serif);
  font-style: italic;
  color: var(--gold-light);
  font-size: 1.15rem;
}

/* Modal Body Content */
.modal-body {
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
  gap: 2.5rem;
}

.modal-grid-layout {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 2.5rem;
}

.modal-main-desc {
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--text-main);
  margin-bottom: 1.75rem;
}

.modal-section-title {
  font-size: 1.25rem;
  font-family: var(--font-serif);
  color: var(--text-pure);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.modal-highlights-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.modal-highlight-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  font-size: 0.95rem;
  color: var(--text-main);
}

.modal-highlight-item svg {
  color: var(--gold-prime);
  flex-shrink: 0;
  margin-top: 3px;
}

/* Quick Facts Sidebar Card */
.modal-sidebar-card {
  background: rgba(11, 36, 27, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-md);
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.modal-info-row {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding-bottom: 0.85rem;
}

.modal-info-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.info-label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-prime);
}

.info-val {
  font-size: 0.92rem;
  color: var(--text-pure);
}

/* ==========================================================================
   SAFETY INFORMATION CARDS (PRECAUTION & MAJOR WARNING)
   ========================================================================== */
.safety-cards-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

/* Precaution Card */
.safety-card-precaution {
  background: var(--precaution-bg);
  border: 1px solid var(--precaution-border);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.safety-header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--precaution-green);
}

.safety-body {
  font-size: 0.92rem;
  color: #D5F5EE;
  line-height: 1.5;
}

/* Major Safety Warning Card */
.safety-card-warning {
  background: var(--warning-bg);
  border: 1px solid var(--warning-border);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.safety-card-warning .safety-header {
  color: var(--warning-amber);
}

.safety-card-warning .safety-body {
  font-size: 0.92rem;
  color: #FEF3C7;
  line-height: 1.5;
}

/* Transit & How to Reach Section */
.transit-box {
  background: rgba(11, 36, 27, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  padding: 1.5rem;
}

.transit-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.transit-item {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.transit-title {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gold-light);
}

.transit-desc {
  font-size: 0.88rem;
  color: var(--text-muted);
}

/* Modal Footer Actions */
.modal-footer-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 1.75rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.coordinates-pill {
  font-family: monospace;
  font-size: 0.85rem;
  color: var(--text-muted);
  background: rgba(0, 0, 0, 0.3);
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

/* --------------------------------------------------------------------------
   FOOTER (EDITORIAL LUXURY)
   -------------------------------------------------------------------------- */
.footer {
  background: #030E09;
  border-top: 1px solid var(--glass-border);
  padding: 6rem 0 3rem;
  position: relative;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1.5fr;
  gap: 3.5rem;
  margin-bottom: 4.5rem;
}

.footer-brand-desc {
  font-size: 0.95rem;
  color: var(--text-muted);
  max-width: 320px;
  margin-top: 1rem;
  line-height: 1.6;
}

.footer-tagline {
  font-family: var(--font-serif);
  font-style: italic;
  color: var(--gold-light);
  margin-top: 0.75rem;
}

.footer-col-title {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  color: var(--text-pure);
  margin-bottom: 1.25rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-link {
  font-size: 0.9rem;
  color: var(--text-muted);
  transition: color var(--transition-fast), transform var(--transition-fast);
  display: inline-block;
}

.footer-link:hover {
  color: var(--gold-prime);
  transform: translateX(4px);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-muted);
  font-size: 0.85rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.made-for-explorers {
  font-family: var(--font-serif);
  font-style: italic;
  color: var(--gold-prime);
}

/* --------------------------------------------------------------------------
   ANIMATIONS & SCROLL REVEALS
   -------------------------------------------------------------------------- */
.fade-up {
  opacity: 0;
  transform: translateY(35px);
  transition: opacity 0.8s var(--ease-luxury), transform 0.8s var(--ease-luxury);
  will-change: opacity, transform;
}

.fade-up.in-view {
  opacity: 1;
  transform: translateY(0);
}

/* Delay helpers */
.delay-1 { transition-delay: 0.1s; }
.delay-2 { transition-delay: 0.2s; }
.delay-3 { transition-delay: 0.3s; }
.delay-4 { transition-delay: 0.4s; }

/* --------------------------------------------------------------------------
   RESPONSIVE DESIGN (MOBILE & TABLET UX)
   -------------------------------------------------------------------------- */
