/* ==========================================================================
   9. CANVAS CONFETTI ENGINE (PURE VANILLA JAVASCRIPT)
   ========================================================================== */
let confettiCanvas, confettiCtx;
let confettiParticles = [];

function initConfettiCanvas() {
  confettiCanvas = document.getElementById("unlock-confetti-canvas");
  if (!confettiCanvas) {
    confettiCanvas = document.createElement("canvas");
    confettiCanvas.id = "unlock-confetti-canvas";
    document.body.appendChild(confettiCanvas);
  }
  confettiCtx = confettiCanvas.getContext("2d");

  function resizeCanvas() {
    confettiCanvas.width = window.innerWidth;
    confettiCanvas.height = window.innerHeight;
  }
  resizeCanvas();
  window.addEventListener("resize", resizeCanvas);
}

function triggerUnlockConfetti() {
  if (!confettiCtx) return;

  const colors = ["#C5A059", "#DFC27D", "#10B981", "#34D399", "#FFFFFF", "#F59E0B"];
  const particleCount = 75;

  for (let i = 0; i < particleCount; i++) {
    confettiParticles.push({
      x: window.innerWidth / 2 + (Math.random() - 0.5) * 200,
      y: window.innerHeight * 0.35,
      vx: (Math.random() - 0.5) * 16,
      vy: Math.random() * -14 - 4,
      size: Math.random() * 8 + 4,
      color: colors[Math.floor(Math.random() * colors.length)],
      rotation: Math.random() * 360,
      rotationSpeed: (Math.random() - 0.5) * 12,
      opacity: 1,
      gravity: 0.45
    });
  }

  if (confettiParticles.length === particleCount) {
    animateConfetti();
  }
}

function animateConfetti() {
  if (!confettiParticles.length) {
    confettiCtx.clearRect(0, 0, confettiCanvas.width, confettiCanvas.height);
    return;
  }

  confettiCtx.clearRect(0, 0, confettiCanvas.width, confettiCanvas.height);

  for (let i = confettiParticles.length - 1; i >= 0; i--) {
    const p = confettiParticles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += p.gravity;
    p.rotation += p.rotationSpeed;
    p.opacity -= 0.012;

    if (p.opacity <= 0 || p.y > window.innerHeight) {
      confettiParticles.splice(i, 1);
      continue;
    }

    confettiCtx.save();
    confettiCtx.translate(p.x, p.y);
    confettiCtx.rotate((p.rotation * Math.PI) / 180);
    confettiCtx.fillStyle = p.color;
    confettiCtx.globalAlpha = p.opacity;
    confettiCtx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
    confettiCtx.restore();
  }

  requestAnimationFrame(animateConfetti);
}

